module edn_jpeg_dct
fn put64(mut out &u8,pos usize,value i64){u:=u64(value);for j in 0..8{unsafe{out[pos+j]=u8(u>>(8*j))}}}
fn narrow(x i64)i16{return i16(x)}
fn line(mut d &i16,base usize,k usize,m int,n int,r &i16){mut t:=[12]i64{};for j in 0..4{unsafe{t[j]=i64(d[base+k*j])+i64(d[base+k*(7-j)]);t[7-j]=i64(d[base+k*j])-i64(d[base+k*(7-j)])}};t[8]=t[0]+t[3];t[9]=t[0]-t[3];t[10]=t[1]+t[2];t[11]=t[1]-t[2];unsafe{d[base]=narrow((t[8]+t[10])>>m);d[base+4*k]=narrow((t[8]-t[10])>>m);t[8]=i64(i16(t[11]+t[9]))*i64(r[10]);d[base+2*k]=narrow(t[8]+i64(i16((t[9]*i64(r[9]))>>n)));d[base+6*k]=narrow(t[8]+i64(i16((t[11]*i64(r[11]))>>n)));t[0]=i64(i16(t[4]+t[7]))*i64(r[2]);t[1]=i64(i16(t[5]+t[6]))*i64(r[0]);t[2]=t[4]+t[6];t[3]=t[5]+t[7];t[8]=i64(i16(t[2]+t[3]))*i64(r[8]);t[2]=i64(i16(t[2]))*i64(r[1])+t[8];t[3]=i64(i16(t[3]))*i64(r[3])+t[8];d[base+7*k]=narrow(i64(i16(t[4]*i64(r[4])+t[0]+t[2]))>>n);d[base+5*k]=narrow(i64(i16(t[5]*i64(r[6])+t[1]+t[3]))>>n);d[base+3*k]=narrow(i64(i16(t[6]*i64(r[5])+t[1]+t[2]))>>n);d[base+k]=narrow(i64(i16(t[7]*i64(r[7])+t[0]+t[3]))>>n)}}
@[export:'edn_jpeg_dct']
pub fn edn_jpeg_dct(values &i64,length usize,mut output &u8,capacity usize)i64{unsafe{if values==nil||length!=76{return -1};mut d:=[64]i16{};mut r:=[12]i16{};for i in 0..64{if values[i]< -8||values[i]>8{return -1};d[i]=i16(values[i])};for i in 0..12{if values[64+i]< -32||values[64+i]>31{return -1};r[i]=i16(values[64+i])};if output==nil||capacity<512{return -2};for row in 0..8{line(&d[0],row*8,1,0,13,&r[0])};for col in 0..8{line(&d[0],col,8,3,16,&r[0])};for i in 0..64{put64(output,8*i,i64(d[i]))};return 512}}
